import {defaults,evaluate,validateField,validateSettings,MODEL_VERSION} from './engine.mjs';
import {readState,persist,makePlan,validatePlan,demoField} from './storage.mjs';
import {createDataClient} from './data.mjs';
import {esc,icon,renderView,plannerResults,compareResults,fieldForm} from './views.mjs';
import {mountScenes} from './field3d.mjs';
import {photoAlt,cropPhoto,photoCreditsHTML} from './photos.mjs';
import {crops} from './engine.mjs';
const $=id=>document.getElementById(id),client=createDataClient();
let storage;try{storage=localStorage}catch{storage={getItem(){return null},setItem(){throw Error('Browser storage is unavailable.')}}}
const initial=readState(storage);let state=initial.state,record=null,loading=false,error='',loadId=0,toastTimer,saveTimer;
if(!state.fields.some(f=>f.id===state.activeFieldId))state.activeFieldId=state.fields[0]?.id||'';
const pages=[['home','Welcome','home'],['dashboard','Overview','dashboard'],['fields','My fields','fields'],['planner','Rotation planner','planner'],['compare','Compare & simulate','compare'],['evidence','Evidence library','evidence'],['plans','Saved plans','plans']];
const field=()=>state.fields.find(f=>f.id===state.activeFieldId);
function settings(){const f=field();if(!f)return {...defaults};if(!state.drafts[f.id])state.drafts[f.id]={...defaults,firstIrrigation:f.irrigation,secondIrrigation:f.irrigation};return state.drafts[f.id]}
function route(){const raw=location.hash.slice(1)||'home';return raw.startsWith('plan/')?'plan':raw==='snapshots'?'snapshots':pages.some(p=>p[0]===raw)?raw:'home'}
function context(){const c={state,field:field(),settings:settings(),record,loading,error,route:route()};if(record&&!loading&&!error&&c.field){try{c.result=evaluate(record,c.field,c.settings);c.baseline=evaluate(record,c.field,{...c.settings,rainChange:0,heatChange:0,secondRainChange:0,secondHeatChange:0,firstIrrigation:c.field.irrigation,secondIrrigation:c.field.irrigation})}catch(e){c.error=e.message}}if(c.route==='plan'){let id;try{id=decodeURIComponent(location.hash.slice(6))}catch{}c.plan=state.plans.find(p=>p.id===id)}return c}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),6500)}
function saveQuiet(){try{persist(storage,state);return true}catch(e){toast('Your change is available in this session, but could not be saved on this device. Export important plans.');return false}}
function transaction(fn){const previous=structuredClone(state);try{fn();persist(storage,state);return true}catch(e){state=previous;toast(`Could not save: ${e.message}. Export or remove an older plan if storage is full.`);return false}}
function render(){const current=route();$('navigation').innerHTML=pages.map(([id,label,ic])=>`<a href="#${id}" ${current===id||(current==='plan'&&id==='plans')?'class="active" aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='plans'?`<small>${state.plans.length}</small>`:''}</a>`).join('');$('breadcrumb').textContent=pages.find(p=>p[0]===current)?.[1]||'Saved plan';$('active-field').innerHTML=state.fields.length?state.fields.map(f=>`<option value="${esc(f.id)}" ${f.id===state.activeFieldId?'selected':''}>${esc(f.name)}</option>`).join(''):'<option value="">No fields yet</option>';$('main').innerHTML=renderView(context());mountScenes($('main'));document.title=`TerraPlan · ${pages.find(p=>p[0]===current)?.[1]||'Saved plan'}`}
function updateResults(){const c=context();if(route()==='planner'&&$('planner-results'))$('planner-results').innerHTML=plannerResults(c);else if(route()==='compare'&&$('compare-results'))$('compare-results').innerHTML=compareResults(c);else render()}
async function loadField(){const id=++loadId,f=field();client.cancel();record=null;error='';loading=Boolean(f);render();if(!f)return;try{const response=await client.load(f);if(id!==loadId||!response.current())return;record=response.record}catch(e){if(id!==loadId)return;error=e.name==='AbortError'?'NASA request timed out or was interrupted. Try again or open the saved Pune demo.':e.message}finally{if(id===loadId){loading=false;render()}}}
function navigate(path){if(location.hash===`#${path}`){render();window.scrollTo({top:0})}else location.hash=path}
function openDialog(html){$('dialog-content').innerHTML=html;$('dialog').showModal()}
function closeDialog(){$('dialog').close();$('dialog-content').innerHTML=''}
function confirmDialog(title,body,action,id){openDialog(`<div class="dialog-heading"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">×</button></div><p class="muted">${esc(body)}</p><div class="dialog-actions"><button class="secondary" data-action="close-dialog">Cancel</button><button class="primary danger-button" data-action="${action}" data-id="${esc(id)}">Remove</button></div>`)}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function syncNavigation(){const hidden=window.innerWidth<=700&&!$('sidebar').classList.contains('open');$('sidebar').inert=hidden;$('sidebar').setAttribute('aria-hidden',String(hidden))}
$('mobile-menu').addEventListener('click',()=>{const expanded=$('sidebar').classList.toggle('open');$('mobile-menu').setAttribute('aria-expanded',expanded);syncNavigation()});
window.addEventListener('resize',syncNavigation);syncNavigation();
document.querySelector('.skip-link').addEventListener('click',event=>{event.preventDefault();$('main').focus();$('main').scrollIntoView()});
window.addEventListener('hashchange',()=>{render();$('sidebar').classList.remove('open');$('mobile-menu').setAttribute('aria-expanded','false');syncNavigation();window.scrollTo({top:0});$('main').focus({preventScroll:true})});
$('active-field').addEventListener('change',()=>{state.activeFieldId=$('active-field').value;saveQuiet();loadField()});
document.addEventListener('input',event=>{const el=event.target,key=el.dataset.setting;if(!key)return;const value=key==='priority'?el.value:+el.value;settings()[key]=value;try{validateSettings(settings())}catch(e){toast(e.message);return}document.querySelectorAll(`[data-output="${key}"]`).forEach(o=>{o.textContent=`${value}${key.includes('Heat')||key==='heatChange'?'°C':key.includes('Rain')||key==='rainChange'?'%':' mm'}`});updateResults();clearTimeout(saveTimer);saveTimer=setTimeout(saveQuiet,300)});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.snapshot){state.comparePlanIds=state.comparePlanIds||[];if(el.checked){if(state.comparePlanIds.length>=2){el.checked=false;toast('Choose two saved plans to compare.');return}state.comparePlanIds.push(el.dataset.snapshot)}else state.comparePlanIds=state.comparePlanIds.filter(id=>id!==el.dataset.snapshot);saveQuiet();render();return}if(!el.dataset.compare)return;const id=el.dataset.compare;if(el.checked){if(state.compare.length>=3){el.checked=false;toast('Choose up to three rotations. Uncheck one to add another.');return}state.compare.push(id)}else state.compare=state.compare.filter(x=>x!==id);saveQuiet();updateResults()});
document.addEventListener('click',async event=>{
 const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;
 if(action==='close-dialog'){closeDialog();return}
 if(action==='photo-credits'){try{const response=await fetch('./assets/photo-credits.json');if(!response.ok)throw Error('Photo credits are unavailable.');openDialog(photoCreditsHTML(await response.json()))}catch(e){toast(e.message)}return}
 if(action==='crop-photo'){const key=b.dataset.crop,crop=crops[key];if(!Object.hasOwn(crops,key))return;openDialog(`<div class="dialog-heading"><div><div class="eyebrow">A CLOSER LOOK AT THE CROP</div><h2>${crop.name}</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">×</button></div><div class="crop-detail-photo">${cropPhoto(key)}</div><p class="muted">${photoAlt[key]}. Reference photograph; not the selected field.</p><dl class="metadata"><div><dt>Model crop group</dt><dd>${crop.legume?'Pulse / legume':'Cereal / grass'}</dd></div><div><dt>Assumed water demand</dt><dd>${crop.water} mm per crop${crop.waterRange?` · FAO context range ${crop.waterRange.join('–')} mm`:' · illustrative constant'}</dd></div><div><dt>Model heat threshold</dt><dd>${crop.heat}°C · illustrative, not locally validated</dd></div></dl><div class="actions crop-detail-actions"><a href="#planner" class="secondary" data-action="close-dialog">Explore rotations →</a><button class="text-button" data-action="photo-credits">Photo source & license ↗</button></div>`);return}
 if(action==='new-field'||action==='edit-field'){openDialog(fieldForm(action==='edit-field'?state.fields.find(f=>f.id===id):null));return}
 if(action==='select-field'){state.activeFieldId=id;saveQuiet();navigate('dashboard');await loadField();return}
 if(action==='delete-field'){const f=state.fields.find(f=>f.id===id);confirmDialog('Remove this field?',`${f.name} will be removed from this device. Saved plan snapshots will remain. You can restore a demo field later.`,'confirm-delete-field',id);return}
 if(action==='confirm-delete-field'){if(transaction(()=>{state.fields=state.fields.filter(f=>f.id!==id);delete state.drafts[id];if(state.activeFieldId===id)state.activeFieldId=state.fields[0]?.id||''})){closeDialog();await loadField();toast('Field removed. Saved plans were preserved.')}return}
 if(action==='demo'){let f=state.fields.find(f=>f.id==='demo-pune');if(!f){f=demoField();state.fields.push(f)}state.activeFieldId=f.id;state.drafts[f.id]={...defaults};saveQuiet();navigate('dashboard');await loadField();toast('Pune demo opened. The profile is illustrative; the NASA history is real.');return}
 if(action==='reload'){await loadField();return}
 if(action==='reset-settings'){if(!field())return;state.drafts[field().id]={...defaults,firstIrrigation:field().irrigation,secondIrrigation:field().irrigation};saveQuiet();render();return}
 if(action==='preset'){const s=settings(),irrigation=field()?.irrigation??200;s.rainChange=s.secondRainChange=0;s.heatChange=s.secondHeatChange=0;s.firstIrrigation=s.secondIrrigation=irrigation;if(b.dataset.preset==='hotdry'){s.rainChange=s.secondRainChange=-40;s.heatChange=s.secondHeatChange=3;s.firstIrrigation=s.secondIrrigation=0}else if(b.dataset.preset==='water')s.firstIrrigation=s.secondIrrigation=irrigation*.5;saveQuiet();render();return}
 if(action==='save-plan'){const c=context();if(!c.result||!c.result.ranked.some(r=>r.eligible)){toast('Choose a complete season with at least one eligible rotation before saving.');return}openDialog(`<form id="save-plan-form"><div class="dialog-heading"><div><div class="eyebrow">KEEP THE REASONING</div><h2>Save your planning snapshot.</h2></div><button type="button" data-action="close-dialog" class="icon-button" aria-label="Close dialog">×</button></div><label class="form-label">Plan name<input name="name" required maxlength="80" value="${esc(c.field.name)} · ${c.settings.year} rotation"></label><p class="muted">Includes your field inputs, both-season scenario, NASA record and model ${MODEL_VERSION}. Stored on this device; export JSON for a backup.</p><p class="form-error" id="form-error" role="alert"></p><button class="primary full" type="submit">Save plan ${icon('plans')}</button></form>`);return}
 if(action==='delete-plan'){const p=state.plans.find(p=>p.id===id);confirmDialog('Remove this saved plan?',`Remove “${p.name}” from this device? Export a copy first if you want to keep its snapshot.`,'confirm-delete-plan',id);return}
 if(action==='confirm-delete-plan'){if(transaction(()=>state.plans=state.plans.filter(p=>p.id!==id))){closeDialog();render();toast('Saved plan removed.')}return}
 if(action==='export-plan'){const p=state.plans.find(p=>p.id===id);if(p){download(p,'terraplan-v2-plan.json');toast('Plan export prepared, including its source record.')}return}
 if(action==='export-dataset'&&record){download(record,'terraplan-nasa-history.json');return}
 if(action==='print-plan'){window.print();return}
 if(action==='import-plan'){$('import-file').click();return}
});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!['field-form','save-plan-form'].includes(form.id))return;event.preventDefault();
 if(form.id==='field-form'){try{const data=new FormData(form),old=state.fields.find(f=>f.id===form.dataset.id),next={id:old?.id||crypto.randomUUID(),name:data.get('name').trim(),lat:+data.get('lat'),lon:+data.get('lon'),area:+data.get('area'),soil:data.get('soil'),previous:data.get('previous'),irrigation:+data.get('irrigation'),demo:false};validateField(next);if(!old&&state.fields.length>=20)throw Error('This device supports up to 20 field profiles.');if(transaction(()=>{if(old)state.fields[state.fields.findIndex(f=>f.id===old.id)]=next;else state.fields.push(next);state.activeFieldId=next.id;state.drafts[next.id]={...(state.drafts[next.id]||defaults),firstIrrigation:next.irrigation,secondIrrigation:next.irrigation}})){closeDialog();await loadField();toast('Field profile saved.')}}catch(e){$('form-error').textContent=e.message}return}
 if(form.id==='save-plan-form'){const name=new FormData(form).get('name').trim(),c=context();if(!name){$('form-error').textContent='Give this plan a name.';return}if(!c.result){$('form-error').textContent='The current dataset is not ready.';return}if(state.plans.length>=20){$('form-error').textContent='Export and remove an older plan before saving more than 20 snapshots.';return}const plan=makePlan(name,c.field,c.settings,c.record,c.result);if(transaction(()=>state.plans.push(plan))){closeDialog();navigate(`plan/${plan.id}`);toast('Plan saved with its original inputs and source record.')}}
});
$('import-file').addEventListener('change',async event=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;try{if(file.size>2_000_000)throw Error('Plan files must be smaller than 2 MB.');const p=validatePlan(JSON.parse(await file.text()));p.result=evaluate(p.dataset,p.field,p.settings);p.id=crypto.randomUUID();p.imported=true;if(state.plans.length>=20)throw Error('Export and remove an older snapshot before importing more plans.');if(transaction(()=>state.plans.push(p))){navigate(`plan/${p.id}`);toast('Plan imported. Scores were recalculated from its saved observations.')}}catch(e){toast(`Import failed: ${e.message}`)}});
window.addEventListener('beforeunload',()=>{if(saveTimer){clearTimeout(saveTimer);try{persist(storage,state)}catch{}}});
loadField();if(initial.warning)toast(initial.warning);
